const inItem = $input.first().json;
const body = inItem.body || inItem;
if (!body || !body.data || !Array.isArray(body.data.fields)) {
  throw new Error('invalid_tally_payload: missing data.fields');
}
const data = body.data;
const byLabel = {};
for (const f of data.fields) {
  if (f.label) byLabel[f.label] = f.value;
}
const pick = (k) => {
  const v = byLabel[k];
  if (Array.isArray(v)) return v.length ? String(v[0]) : '';
  return v == null ? '' : String(v);
};
const pickJoin = (k) => {
  const v = byLabel[k];
  if (Array.isArray(v)) return v.join(', ');
  return v == null ? '' : String(v);
};
const hubspot_id = pick('hubspot_id').trim();
const submission_id = data.submissionId || data.responseId;
if (!submission_id) throw new Error('missing_submission_id');
return { json: {
  submission_id,
  tally_form_id: data.formId || '',
  submitted_at: body.createdAt || new Date().toISOString(),
  hubspot_id,
  has_hubspot_id: hubspot_id.length > 0,
  email_prefill: pick('email_prefill').trim(),
  shop_name: pick('Shop name'),
  entity_name: pick('Entity name (optional)'),
  delivery_address: pick('Delivery address'),
  manager_name: pick('Manger/owner name'),
  form_email: pick('Email'),
  form_phone: pick('Phone'),
  account_contact: pick('Account contact?'),
  account_name: pick('Account name'),
  account_email: pick('Account email'),
  account_phone: pick('Account phone'),
  payment_term_selection: pick('Payments'),
  legal_entity: pick('Legal entity name'),
  abn_acn: pick('ABN / ACN'),
  credit_term: pickJoin('Credit term  '),
  credit_limit: pick('Credit limit'),
  raw_payload_json: JSON.stringify(body)
} };

const hubspotResp = $input.first().json;
const inErr = hubspotResp && hubspotResp.error;
const is404 = inErr && (inErr.httpCode === '404' || (inErr.message && inErr.message.includes('404')));
const matched = !inErr && hubspotResp && hubspotResp.id;
return { json: {
  matched_via: matched ? 'hubspot_id' : (is404 ? 'invalid_id' : 'lookup_error'),
  hubspot_company_id: matched ? String(hubspotResp.id) : '',
  matched_company_name: matched ? ((hubspotResp.properties && hubspotResp.properties.name) || '') : '',
  forward_guard_flag: false
} };

const m = $input.first().json;
const v = $('Validate & Normalize').item.json;
const now = new Date().toISOString();
const airtable_body = {
  records: [{
    fields: {
      submission_id: v.submission_id,
      tally_form_id: v.tally_form_id,
      submitted_at: v.submitted_at,
      hubspot_company_id: m.hubspot_company_id || '',
      matched_via: m.matched_via,
      forward_guard_flag: !!m.forward_guard_flag,
      shop_name: v.shop_name,
      entity_name: v.entity_name,
      abn: v.abn_acn,
      delivery_address: v.delivery_address,
      form_email: v.form_email,
      form_phone: v.form_phone,
      account_contact_name: v.account_name,
      account_contact_email: v.account_email,
      account_contact_phone: v.account_phone,
      payment_term_selection: v.payment_term_selection,
      raw_payload_json: v.raw_payload_json,
      status: 'under review',
      created_at: now,
      updated_at: now
    }
  }],
  typecast: true
};
return { json: { airtable_body_str: JSON.stringify(airtable_body) } };
